            var v = c.variance || 0;
            var vColor = v > 1000 ? '#e53935' : (v < -1000 ? '#388e3c' : '#888');
            var vStr = (v >= 0 ? '+' : '') + '$' + v.toLocaleString('en-AU',{maximumFractionDigits:0});

            html = html + '<tr style="background:' + bg + ';cursor:pointer;" onclick="frappe.set_route(\'Form\',\'BIM Cost Item\',\'' + c.name + '\')">' +
